'use strict';
const lessons=[
{title:'Ритм, доли и фразы',time:'8 мин',body:'В большинстве танцевальных треков размер 4/4: четыре доли образуют такт. Считай «раз, два, три, четыре» и начинай заново. Несколько тактов складываются в музыкальную фразу — часто 8 или 16 тактов. На её границе удобно запускать следующий трек.',task:'Включи house-трек. Отсчитай 8 тактов по 4 доли. Заметь, появляется ли новый инструмент или меняется аранжировка на следующей «единице». Повтори три раза.',answer:'В 8 тактах размера 4/4 — 32 доли. Изменение аранжировки помогает найти границу фразы, но не обязано происходить каждые 8 тактов.'},
{title:'Знакомство с оборудованием',time:'10 мин',body:'Деки воспроизводят треки, а микшер объединяет их. Gain регулирует входной уровень, фейдер канала — его громкость в миксе, EQ — частоты. Предпрослушивание CUE позволяет слушать следующий трек в наушниках до вывода в зал.',task:'Найди на своём контроллере или в DJ-программе Play, Cue, tempo, gain, EQ и фейдер. Убери фейдер второго канала и включи его CUE в наушниках. Затем плавно подними фейдер.',answer:'CUE в наушниках не должен сам по себе выводить трек в общий микс. Следи за индикаторами: постоянная красная зона означает слишком высокий уровень.'},
{title:'Битмэтчинг: сводим темп',time:'15 мин',body:'Сначала выровняй BPM двух треков регулятором tempo. Затем совмести первые доли с помощью jog или pitch bend. Если доли постепенно расходятся, темп ещё отличается. Если расстояние между ними постоянно, нужно поправить положение трека.',task:'Возьми два трека с чётким ритмом и близким BPM. Совмести темп, запусти второй на первую долю фразы и слушай 16 тактов. Подправляй небольшими движениями.',answer:'Постепенное расхождение исправляют темпом. Постоянное смещение — кратковременным ускорением или замедлением jog. Одинаковые цифры BPM не гарантируют точного совпадения.'},
{title:'Плавный переход и EQ',time:'12 мин',body:'Два мощных баса одновременно часто делают микс перегруженным. При вводе второго трека ослабь его низкие частоты, затем на границе фразы постепенно передай ему бас, убирая низ первого. Слушай результат и контролируй общий уровень.',task:'Сделай переход за 16 тактов. Первые 8 — вводи второй трек без баса. В следующие 8 передай бас и выведи первый трек. Запиши переход и прослушай.',answer:'Хороший переход сохраняет ритм и понятный баланс. Не нужно выкручивать всё по шаблону: объём коррекции зависит от треков и типа эквалайзера.'},
{title:'Подбор треков и энергия',time:'10 мин',body:'Сет строится не только на BPM. Учитывай плотность аранжировки, вокал, настроение и тональность. Два вокала часто мешают друг другу. Заранее отмечай точки входа и выхода и слушай пары треков вместе.',task:'Выбери 5 треков: спокойное начало, развитие, более энергичная середина и завершение. Запиши для каждой пары причину перехода. Проверь, не конфликтуют ли мелодии и вокал.',answer:'Удачная последовательность звучит связно и оставляет место развитию. Совместимость по тональности — полезная подсказка, но окончательное решение принимает слух.'},
{title:'Запиши свой первый сет',time:'20 мин',body:'Подготовь короткий сет из 5 треков. Проверь уровни и запись, заранее прослушай переходы. Во время исполнения оставляй запас громкости и не перегружай микс эффектами. После записи оцени ритм, баланс и общую историю.',task:'Запиши 15–20 минут. Прослушай без перемотки и отметь время трёх моментов, которые хочешь улучшить. Повтори только эти переходы, затем запиши сет ещё раз.',answer:'Первый сет не обязан быть безупречным. Три конкретных наблюдения — например, расходятся доли, скачет громкость или сталкивается вокал — полезнее общей оценки «плохо».'}
];
let completed=[];try{const saved=JSON.parse(localStorage.getItem('beatcraft-progress')||'[]');if(Array.isArray(saved))completed=[...new Set(saved.filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length))]}catch{}let active=0;
const $=id=>document.getElementById(id);
function render(){ $('lessons').replaceChildren();lessons.forEach((l,i)=>{const b=document.createElement('button');b.className='lesson-btn'+(i===active?' active':'');b.setAttribute('aria-current',i===active?'step':'false');b.innerHTML=`<span class="lesson-index">${String(i+1).padStart(2,'0')}</span><span><strong>${l.title}</strong><small>${l.time} · теория + практика</small></span><span class="lesson-check">${completed.includes(i)?'✓':'↗'}</span>`;b.onclick=()=>{active=i;render()};$('lessons').append(b)});const l=lessons[active];$('lesson-number').textContent=`УРОК ${String(active+1).padStart(2,'0')}`;$('lesson-meta').textContent=`${l.time.toUpperCase()} / ТЕОРИЯ + ПРАКТИКА`;$('lesson-title').textContent=l.title;$('lesson-body').textContent=l.body;$('lesson-task').textContent=l.task;$('lesson-answer').textContent=l.answer;document.querySelector('.lesson-content details').open=false;$('complete').innerHTML=completed.includes(active)?'Пройдено ✓ <span>Повторить урок</span>':'Урок пройден <span>↗</span>';$('count').textContent=`${completed.length} / 6 уроков`;$('bar').style.width=`${completed.length/6*100}%`}
$('complete').onclick=()=>{if(completed.includes(active)){completed=completed.filter(i=>i!==active)}else{completed.push(active);if(active<5)active++}try{localStorage.setItem('beatcraft-progress',JSON.stringify(completed))}catch{$('storage-note').textContent='Браузер не разрешил сохранение. Прогресс доступен до закрытия страницы.'}render()};render();
let ctx,timer=null,beat=0,taps=[];function clickBeat(){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=beat%4===0?1000:700;g.gain.setValueAtTime(.12,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.05);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.06);beat++}function stop(){clearInterval(timer);timer=null;$('metro').textContent='▶ Метроном';$('metro').setAttribute('aria-pressed','false')}function start(){clickBeat();timer=setInterval(clickBeat,60000/Number($('tempo').value));$('metro').textContent='■ Остановить';$('metro').setAttribute('aria-pressed','true')}
$('metro').onclick=async()=>{if(timer){stop();return}try{ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();beat=0;start()}catch{$('tap-info').textContent='Звук недоступен в этом браузере. TAP работает без звука.'}};
$('tempo').oninput=()=>{$('bpm').textContent=$('tempo').value;if(timer){stop();start()}};
$('tap').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2000)taps=[];taps.push(now);if(taps.length>9)taps.shift();if(taps.length<4){$('tap-info').textContent=`Ещё ${4-taps.length} нажатия для измерения`;return}const bpm=Math.round(60000*(taps.length-1)/(now-taps[0]));$('bpm').textContent=bpm;$('tap-info').textContent=`Темп по ${taps.length} нажатиям${bpm<60||bpm>180?' · вне диапазона метронома 60–180 BPM':''}`;if(bpm>=60&&bpm<=180){$('tempo').value=bpm;if(timer){stop();start()}}};document.addEventListener('visibilitychange',()=>{if(document.hidden&&timer)stop()});
